1	# JSON Schema (draft 2020-12), записанная в YAML. Формат записи спеки: один файл = одна система
2	# (или часть системы: файлы с одинаковым system.id склеиваются при render/to_db).
3	#
4	# Правила clean-room: в `behavior`, `title`, `own_name`, `goal` — только свои слова и свои имена.
5	# Имена/идентификаторы/строки референса допустимы ТОЛЬКО в `source_refs` / `source_ref`
6	# и в `candidates` (рабочая зона скелета, в публичный рендер не идёт).
7	$schema: "https://json-schema.org/draft/2020-12/schema"
8	title: reverse-kit spec record
9	type: object
10	required: [schema, game, system]
11	additionalProperties: false
12	properties:
13	  schema: {const: "reverse-kit-record/1"}
14	  game: {type: string, pattern: "^[a-z0-9][a-z0-9_-]*$", description: "slug игры, как в mechanics-db"}
15	  status: {enum: [skeleton, draft, reviewed], default: draft,
16	           description: "skeleton — только кандидаты, to_db пропускает; draft — написано агентом; reviewed — сверено"}
17	  system:
18	    type: object
19	    required: [id, slug, title]
20	    additionalProperties: false
21	    properties:
22	      id: {type: string, pattern: "^[0-9]{2}[a-z]?$", description: "номер системы 00-30 (+буква для подфайлов)"}
23	      slug: {type: string, pattern: "^[a-z0-9][a-z0-9-]*$"}
24	      title: {type: string}
25	      spec_file: {type: string, description: "имя md-файла при рендере; по умолчанию <id>-<slug>.md"}
26	      buckets: {type: array, items: {type: string}, description: "корзины coverage, покрытые файлом"}
27	  collection: {type: string, pattern: "^[a-z][a-z0-9_]*$",
28	               description: "id коллекции из taxonomy/collections.yaml (53 шт.); по умолчанию для всех rules/catalog файла"}
29	  goal: {type: string, description: "Цель: 1-3 предложения, что даёт игроку/что должно получиться"}
30	  rules:
31	    type: array
32	    items: {$ref: "#/$defs/rule"}
33	  catalog:
34	    type: array
35	    items: {$ref: "#/$defs/row"}
36	  open_questions:
37	    type: array
38	    items: {type: string}
39	  acceptance:
40	    type: array
41	    items: {type: string, description: "проверяемый критерий, желательно с числом"}
42	  candidates:
43	    type: array
44	    description: "Рабочая зона скелета (типы + литералы + поля). Не рендерится и не попадает в БД. Агент превращает в rules/catalog и удаляет."
45	    items: {$ref: "#/$defs/candidate"}
46	  meta:
47	    type: object
48	    description: "Служебное: кто/когда/чем сгенерировано, модель агента, хеш индекса"
49	    additionalProperties: true
50	
51	$defs:
52	  scalar: {type: [number, string, boolean, "null"]}
53	  numval:
54	    description: "число, строка (диапазон/формула) или {value, unit, note, ref}"
55	    oneOf:
56	      - {type: [number, string, boolean]}
57	      - type: array
58	        items: {type: [number, string]}
59	      - type: object
60	        required: [value]
61	        additionalProperties: false
62	        properties:
63	          value: {type: [number, string, boolean, array]}
64	          unit: {type: string}
65	          note: {type: string}
66	          ref: {type: string, description: "источник числа (для verify)"}
67	  numbers:
68	    type: object
69	    additionalProperties: {$ref: "#/$defs/numval"}
70	  rule:
71	    type: object
72	    required: [id, title, behavior]
73	    additionalProperties: false
74	    properties:
75	      id: {type: string, pattern: "^[A-Za-z0-9][A-Za-z0-9_.-]*$"}
76	      title: {type: string}
77	      behavior: {type: string, description: "поведение своими словами; TODO: ... если не написано"}
78	      numbers: {$ref: "#/$defs/numbers"}
79	      conditions: {type: array, items: {type: string}, description: "когда правило действует / исключения"}
80	      source_refs: {type: array, items: {type: string}, description: "Тип.Член или файл:строка референса"}
81	      tags: {type: array, items: {type: string}}
82	      confidence: {enum: [high, medium, low]}
83	      collection: {type: string, pattern: "^[a-z][a-z0-9_]*$"}
84	  row:
85	    type: object
86	    required: [id, kind, own_name]
87	    additionalProperties: false
88	    properties:
89	      id: {type: string, pattern: "^[A-Za-z0-9][A-Za-z0-9_.-]*$"}
90	      kind: {type: string, description: "relic | enemy | boss | spell | status | summon | npc | outfit | attack | pickup | prop | ... (to_db маппит в виды БД)"}
91	      own_name: {type: string, description: "СВОЁ имя; имя референса сюда нельзя"}
92	      numbers: {$ref: "#/$defs/numbers"}
93	      behavior: {type: string}
94	      source_ref: {type: string}
95	      tags: {type: array, items: {type: string}}
96	      collection: {type: string, pattern: "^[a-z][a-z0-9_]*$", description: "переопределяет collection файла"}
97	  candidate:
98	    type: object
99	    required: [type]
100	    additionalProperties: true
101	    properties:
102	      type: {type: string}
103	      bucket: {type: string}
104	      base: {type: string}
105	      kind: {type: string}
106	      file: {type: string}
107	      confidence: {type: number}
108	      data_fields: {type: array, items: {type: object}}
109	      numeric_literals: {type: array, items: {type: object}}
110	      calls: {type: array, items: {type: string}}
111	      todo: {type: string}
112

