using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using ProjectTower.config;
using SheetEdit.sheetUGC;

namespace ProjectTower.steam.ugc;

public class UGCManager
{
	public static int state;

	public const int STATE_UNINITIALIZED = 0;

	public const int STATE_READING = 1;

	public const int STATE_COMPLETE = 2;

	public const int STATE_ERROR = 4;

	public static List<SheetUGCPackage> packages;

	private static Dictionary<ulong, string> readData;

	public static void Initialize()
	{
		packages = new List<SheetUGCPackage>();
	}

	public static void SetData(Dictionary<ulong, string> data)
	{
		readData = data;
		new Thread(ThreadedRead).Start();
	}

	private static void ThreadedRead()
	{
		try
		{
			packages = new List<SheetUGCPackage>();
			ConfigMgr.GetUGCList();
			foreach (KeyValuePair<ulong, string> readDatum in readData)
			{
				SheetUGCPackage sheetUGCPackage = new SheetUGCPackage();
				sheetUGCPackage.publishedFileId = readDatum.Key;
				sheetUGCPackage.directory = readDatum.Value;
				string[] files = Directory.GetFiles(sheetUGCPackage.directory);
				for (int i = 0; i < files.Length; i++)
				{
					if (Path.GetExtension(files[i]).ToLower() == ".sltpkg")
					{
						sheetUGCPackage.fileName = Path.GetFileNameWithoutExtension(files[i]);
						break;
					}
				}
				if (sheetUGCPackage.fileName != null)
				{
					sheetUGCPackage.Read(Path.Combine(sheetUGCPackage.directory, sheetUGCPackage.fileName + ".sltpkg"));
					sheetUGCPackage.previewTexture = Texture2D.FromStream(Game1.graphics.GraphicsDevice, new FileStream(Path.Combine(sheetUGCPackage.directory, Path.GetFileNameWithoutExtension(sheetUGCPackage.previewPath) + ".PNG"), FileMode.Open));
					packages.Add(sheetUGCPackage);
				}
			}
			state = 2;
		}
		catch (Exception ex)
		{
			Console.WriteLine(ex.ToString());
			state = 4;
		}
	}

	internal static Point CheckReplace(string name)
	{
		if (state != 2)
		{
			return new Point(-1, -1);
		}
		for (int i = 0; i < packages.Count; i++)
		{
			if (!packages[i].enabled)
			{
				continue;
			}
			for (int j = 0; j < packages[i].sheets.Count; j++)
			{
				if (packages[i].sheets[j].name == name)
				{
					return new Point(i, j);
				}
			}
		}
		return new Point(-1, -1);
	}
}
using ProjectTower.gamestate;

namespace ProjectTower.steam;

public class SteamDataConversion
{
	private const byte PLACE_0 = 32;

	private const int PLACE_1 = 212;

	private const int PLACE_2 = 44944;

	private const int PLACE_3 = 9528128;

	public static long[] workingBuffer;

	public static string Int8ToString(int i)
	{
		return ((char)((byte)(i % 212) + 32)).ToString() ?? "";
	}

	public static int StringToInt8(string s, int idx)
	{
		if (s.Length < idx + 1)
		{
			return -1;
		}
		return (byte)s[idx] - 32;
	}

	public static string Int16ToString(int i)
	{
		i %= 44944;
		return ((char)((byte)(i / 212) + 32)).ToString() + (char)((byte)(i % 212) + 32);
	}

	public static int StringToInt16(string s, int idx)
	{
		if (s.Length < idx + 2)
		{
			return -1;
		}
		return ((byte)s[idx] - 32) * 212 + ((byte)s[idx + 1] - 32);
	}

	public static string Int24ToString(int i)
	{
		i %= 9528128;
		return ((char)((byte)(i / 44944) + 32)).ToString() + (char)((byte)(i % 44944 / 212) + 32) + (char)((byte)(i % 212) + 32);
	}

	public static int StringToInt24(string s, int idx)
	{
		if (s.Length < idx + 3)
		{
			return -1;
		}
		return ((byte)s[idx] - 32) * 44944 + ((byte)s[idx + 1] - 32) * 212 + ((byte)s[idx + 2] - 32);
	}

	public static int GetRequiredIntArraySize(string s)
	{
		return s.Length / 4 + 1;
	}

	public static void StringToIntArray(string s, int[] i_array, int offset, int len)
	{
		int num = 0;
		long num2 = 1L;
		int num3 = 0;
		for (int i = 0; i < i_array.Length; i++)
		{
			workingBuffer[i] = 0L;
		}
		for (int j = 0; j < s.Length; j++)
		{
			workingBuffer[num3] += (byte)s[j] * num2;
			num2 *= 256;
			num++;
			if (num >= 4)
			{
				num = 0;
				num2 = 1L;
				num3++;
			}
		}
		for (int k = 0; k < len; k++)
		{
			workingBuffer[k] += -2147483648L;
			i_array[k + offset] = (int)workingBuffer[k];
		}
	}

	public static string IntArrayToString(int[] i_array, int offset, int len)
	{
		string text = "";
		for (int i = 0; i < len; i++)
		{
			workingBuffer[i] = i_array[i + offset];
			workingBuffer[i] -= -2147483648L;
		}
		for (int j = 0; j < len; j++)
		{
			long num = workingBuffer[j];
			while (num > 0)
			{
				long num2 = num % 256;
				num /= 256;
				text += (char)(byte)num2;
			}
		}
		return text;
	}

	public static byte[] GetBytesFromString(string str)
	{
		byte[] array = new byte[str.Length];
		for (int i = 0; i < str.Length; i++)
		{
			array[i] = (byte)str[i];
		}
		if (SteamServiceMgr.verbose)
		{
			string text = "";
			for (int j = 0; j < array.Length; j++)
			{
				text = text + ((j != 0) ? "|" : "") + array[j];
			}
			GameConsole.WriteLine("String [" + str + "]");
			GameConsole.WriteLine("to Bytes [" + text + "]");
		}
		return array;
	}

	public static string GetStringFromBytes(byte[] b)
	{
		string text = "";
		for (int i = 0; i < b.Length; i++)
		{
			string text2 = text;
			char c = (char)b[i];
			text = text2 + c;
		}
		if (SteamServiceMgr.verbose)
		{
			string text3 = "";
			for (int j = 0; j < b.Length; j++)
			{
				text3 = text3 + ((j != 0) ? "|" : "") + b[j];
			}
			GameConsole.WriteLine("Bytes [" + text3 + "]");
			GameConsole.WriteLine("to String [" + text + "]");
		}
		return text;
	}
}
