	private static void OnSteamWorkshopUGCDownloaded(RemoteStorageDownloadUGCResult_t param, bool bIOFailure)
	{
		GameConsole.WriteLine("UGC downloaded.");
		if (!bIOFailure)
		{
			GameConsole.WriteLine("Download success.");
		}
		else
		{
			GameConsole.WriteLine("Download failed.");
		}
		GameConsole.WriteLine("Result: " + param.m_eResult);
		string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(Path.GetFileNameWithoutExtension(param.m_pchFileName));
		GameConsole.WriteLine("Downloaded \"" + fileNameWithoutExtension + "\". Installing...");
		GameConsole.WriteLine("- Mod \"" + fileNameWithoutExtension + "\" downloaded!");
		string text = Directory.GetCurrentDirectory() + "\\" + fileNameWithoutExtension + "\\";
		byte[] pvData = new byte[param.m_nSizeInBytes];
		SteamRemoteStorage.UGCRead(param.m_hFile, pvData, param.m_nSizeInBytes, 0u, EUGCReadAction.k_EUGCRead_Close);
		GameConsole.WriteLine("\"" + fileNameWithoutExtension + "\" was installed");
		GameConsole.WriteLine("- Mod \"" + text + "\" extracted!");
	}

	private static void OnUGCQueryCompleted(SteamUGCQueryCompleted_t param, bool bIOFailure)
	{
		if (!bIOFailure)
		{
			try
			{
				GameConsole.WriteLine("Success.");
				GameConsole.WriteLine("Cached data: " + param.m_bCachedData);
				GameConsole.WriteLine("Result: " + param.m_eResult);
				GameConsole.WriteLine("Handle: " + param.m_handle.m_UGCQueryHandle);
				GameConsole.WriteLine("Num Results: " + param.m_unNumResultsReturned);
				GameConsole.WriteLine("Total Results: " + param.m_unTotalMatchingResults);
				SteamUGCDetails_t pDetails = default;
				Dictionary<ulong, string> dictionary = new Dictionary<ulong, string>();
				for (int i = 0; i < param.m_unNumResultsReturned; i++)
				{
					SteamUGC.GetQueryUGCResult(param.m_handle, (uint)i, out pDetails);
					GameConsole.WriteLine("Name: " + pDetails.m_pchFileName);
					GameConsole.WriteLine("Title: " + pDetails.m_rgchTitle);
					GameConsole.WriteLine("Desc: " + pDetails.m_rgchDescription);
					GameConsole.WriteLine("Filename: " + pDetails.m_pchFileName.ToString());
					GameConsole.WriteLine("Filesize: " + pDetails.m_nFileSize);
					GameConsole.WriteLine("Time Added: " + pDetails.m_rtimeAddedToUserList);
					GameConsole.WriteLine("Published File Id: " + pDetails.m_nPublishedFileId.ToString());
					bool itemInstallInfo = SteamUGC.GetItemInstallInfo(pDetails.m_nPublishedFileId, out var punSizeOnDisk, out var pchFolder, 260u, out var punTimeStamp);
					GameConsole.WriteLine("Item installed: " + itemInstallInfo);
					GameConsole.WriteLine("Install state: " + (EItemState)SteamUGC.GetItemState(pDetails.m_nPublishedFileId)/*cast due to constrained. prefix*/);
					if (itemInstallInfo)
					{
						GameConsole.WriteLine("Size: " + punSizeOnDisk);
						if (pchFolder != null)
						{
							GameConsole.WriteLine(("Path: " + pchFolder != null) ? pchFolder : "");
						}
						GameConsole.WriteLine("Timestamp: " + punTimeStamp);
						dictionary.Add(pDetails.m_nPublishedFileId.m_PublishedFileId, pchFolder);
					}
				}
				UGCManager.SetData(dictionary);
				return;
			}
			catch (Exception ex)
			{
				GameConsole.WriteLine("Fatal UGC Error: " + ex.ToString());
				return;
			}
		}
		GameConsole.WriteLine("Failed.");
	}

