	private static void ThreadedRefresh()
	{
		bool flag = true;
		if (verbose)
		{
			GameConsole.WriteLine("Beginning threaded refresh.");
		}
		while (flag)
		{
			if (verbose)
			{
				GameConsole.WriteLine("Top of threaded refresh.");
			}
			if (GameStateManager.gameState == 1)
			{
				GetLeaderboard("SEQ_" + GetLeaderboardAreaName(), 3);
			}
			for (int i = 0; i < 100; i++)
			{
				Thread.Sleep(100);
				if (needsCancel)
				{
					flag = false;
					return;
				}
			}
			while (stalled)
			{
				Thread.Sleep(100);
			}
			if (GameStateManager.gameState == 1)
			{
				GetLeaderboard("MSG_" + GetLeaderboardAreaName(), 7);
			}
			for (int j = 0; j < 100; j++)
			{
				Thread.Sleep(100);
				if (needsCancel)
				{
					flag = false;
					return;
				}
			}
			while (stalled)
			{
				Thread.Sleep(100);
			}
			if (GameStateManager.gameState == 1)
			{
				SteamAPICall_t hAPICall = SteamUserStats.RequestGlobalStats(50);
				GlobalStatsReceived.Set(hAPICall);
			}
			for (int k = 0; k < 100; k++)
			{
				Thread.Sleep(100);
				if (needsCancel)
				{
					flag = false;
					return;
				}
			}
			while (stalled)
			{
				Thread.Sleep(100);
			}
			if (GameStateManager.gameState == 1)
			{
				GetLeaderboard("SANCTUARY", 15);
			}
			for (int l = 0; l < 100; l++)
			{
				Thread.Sleep(100);
				if (needsCancel)
				{
					flag = false;
					return;
				}
			}
			while (stalled)
			{
				if (needsCancel)
				{
					flag = false;
					return;
				}
				Thread.Sleep(100);
			}
			newArea = false;
			while (!newArea)
			{
				if (needsCancel)
				{
					flag = false;
					return;
				}
				Thread.Sleep(100);
			}
		}
	}

