	public static void WriteLeaderboard()
	{
		if (verbose)
		{
			GameConsole.WriteLine("Writing...");
		}
		DateTime utcNow = DateTime.UtcNow;
		_ = utcNow.Minute;
		int num = utcNow.Hour * 100;
		int num2 = utcNow.Day * 10000;
		int num3 = utcNow.Month * 1000000;
		int num4 = (utcNow.Year - 2000) * 100000000;
		int nScore = num + num2 + num3 + num4;
		switch (leaderState.state)
		{
		case 14:
		{
			SteamAPICall_t hAPICall3 = SteamUserStats.UploadLeaderboardScore(m_SteamLeaderboard, ELeaderboardUploadScoreMethod.k_ELeaderboardUploadScoreMethodForceUpdate, nScore, sanctuaryBuffer, sanctuaryBuffer.Length);
			LeaderboardScoreUploaded.Set(hAPICall3);
			break;
		}
		case 6:
		{
			SteamAPICall_t hAPICall4 = SteamUserStats.UploadLeaderboardScore(m_SteamLeaderboard, ELeaderboardUploadScoreMethod.k_ELeaderboardUploadScoreMethodForceUpdate, nScore, messageBuffer, messageBuffer.Length);
			LeaderboardScoreUploaded.Set(hAPICall4);
			break;
		}
		case 10:
		{
			if (verbose)
			{
				for (int i = 0; i < flagsBuffer.Length; i++)
				{
					Console.Write(((i != 0) ? "|" : "") + flagsBuffer[i]);
				}

				}
				Console.WriteLine("");
			}
			SteamAPICall_t hAPICall2 = SteamUserStats.UploadLeaderboardScore(m_SteamLeaderboard, ELeaderboardUploadScoreMethod.k_ELeaderboardUploadScoreMethodForceUpdate, nScore, flagsBuffer, flagsBuffer.Length);
			LeaderboardScoreUploaded.Set(hAPICall2);
			break;
		}
		case 2:
		{
			SteamAPICall_t hAPICall = SteamUserStats.UploadLeaderboardScore(m_SteamLeaderboard, ELeaderboardUploadScoreMethod.k_ELeaderboardUploadScoreMethodForceUpdate, nScore, sequenceBuffer, sequenceBuffer.Length);
			LeaderboardScoreUploaded.Set(hAPICall);
			break;
		}
		}
	}

	public static void ReadLeaderboard(bool friends)
	{
		if (friends)
		{
			SteamAPICall_t hAPICall = SteamUserStats.DownloadLeaderboardEntries(m_SteamLeaderboard, ELeaderboardDataRequest.k_ELeaderboardDataRequestFriends, -10, 10);
			LeaderboardScoresDownloaded.Set(hAPICall);
			return;
		}
		int randomInt = Rand.GetRandomInt(1, SteamUserStats.GetLeaderboardEntryCount(m_SteamLeaderboard) - 1);
		int num = randomInt + 10;
		randomInt = SteamUserStats.GetLeaderboardEntryCount(m_SteamLeaderboard) / 2 + Rand.GetRandomInt(0, 2);
		num = randomInt + 10;
		if (verbose)
		{
			GameConsole.WriteLine("Requesting " + randomInt + " to " + num + ".");
		}
		SteamAPICall_t hAPICall2 = SteamUserStats.DownloadLeaderboardEntries(m_SteamLeaderboard, ELeaderboardDataRequest.k_ELeaderboardDataRequestGlobal, randomInt, num);
		LeaderboardScoresDownloaded.Set(hAPICall2);
	}

