				break;
			case 3:
				leaderState.state = 4;
				ReadLeaderboard(friends: false);
				break;
			case 5:
				leaderState.state = 6;
				WriteLeaderboard();
				break;
			case 7:
				leaderState.state = 8;
				ReadLeaderboard(friends: false);
				break;
			case 9:
				leaderState.state = 10;
				WriteLeaderboard();
				break;
			case 11:
				leaderState.state = 12;
				ReadLeaderboard(friends: false);
				break;
			case 2:
			case 4:
			case 6:
			case 8:
			case 10:
