	public static void OnLeaderboardScoresDownloaded(LeaderboardScoresDownloaded_t pCallback, bool bIOFailure)
	{
		if (verbose)
		{
			GameConsole.WriteLine("Scores downloaded.");
		}
		if (leaderState.state == 12)
		{
			GlobalFlagsMgr.ResetBossFlags();
		}
		int num = Rand.GetRandomInt(0, pCallback.m_cEntryCount);
		if (verbose)
		{
			GameConsole.WriteLine(pCallback.m_cEntryCount + " entries.");
		}
		for (int i = 0; i < pCallback.m_cEntryCount; i++)
		{
			num = (num + 1) % pCallback.m_cEntryCount;
			LeaderboardEntry_t pLeaderboardEntry = default;
			switch (leaderState.state)
			{
			case 16:
			{
				if (sanctuaryBuffer == null)
				{
					sanctuaryBuffer = new int[12];
				}
				SteamUserStats.GetDownloadedLeaderboardEntry(pCallback.m_hSteamLeaderboardEntries, num, out pLeaderboardEntry, sanctuaryBuffer, sanctuaryBuffer.Length);
				int sanctIdx = sanctuaryBuffer[0];
				if (verbose)
				{
					GameConsole.WriteLine("ID: " + pLeaderboardEntry.m_steamIDUser.m_SteamID);
				}
				if (ProcessSanctuaryDownload(sanctIdx, pLeaderboardEntry))
				{
					return;
				}
				break;
			}
			case 12:
				if (flagsBuffer == null)
				{
					flagsBuffer = new int[46];
				}
				SteamUserStats.GetDownloadedLeaderboardEntry(pCallback.m_hSteamLeaderboardEntries, num, out pLeaderboardEntry, flagsBuffer, flagsBuffer.Length);
				if (verbose)
				{
					for (int j = 0; j < flagsBuffer.Length; j++)
					{
						Console.Write(((j != 0) ? "|" : "") + flagsBuffer[j]);
					}
					Console.WriteLine("");
				}
				GlobalFlagsMgr.ProcessBossFlags(flagsBuffer);
				break;
			case 8:
			{
				if (messageBuffer == null)
				{
					messageBuffer = new int[27];
				}
				for (int k = 0; k < messageBuffer.Length; k++)
				{
					messageBuffer[k] = 0;
				}
				SteamUserStats.GetDownloadedLeaderboardEntry(pCallback.m_hSteamLeaderboardEntries, num, out pLeaderboardEntry, messageBuffer, messageBuffer.Length);
				string text = SteamDataConversion.IntArrayToString(messageBuffer, 2, messageBuffer.Length - 2);
				string text2 = "";
				for (int l = 0; l < text.Length; l++)
				{
					if (text[l] > '\0' && text[l] < '\u0080')
					{
						text2 += text[l];
					}
				}
				BottleMessageMgr.AddMessage(loc: new Vector2(messageBuffer[0], messageBuffer[1]), owner: pLeaderboardEntry.m_steamIDUser.ToString(), message: text2, recipient: "", votes: 0, frame: 29f);
				break;
			}
			case 4:
				if (sequenceBuffer == null)
				{
					sequenceBuffer = new int[51];
				}
				SteamUserStats.GetDownloadedLeaderboardEntry(pCallback.m_hSteamLeaderboardEntries, num, out pLeaderboardEntry, sequenceBuffer, sequenceBuffer.Length);
				CharSequenceMgr.AddSequence(pLeaderboardEntry.m_steamIDUser.m_SteamID.ToString(), new Vector2(sequenceBuffer[0], sequenceBuffer[1]));
				break;
			}
			if (verbose)
			{
				GameConsole.WriteLine(pLeaderboardEntry.m_nGlobalRank + ": Friend: " + SteamFriends.GetFriendPersonaName(pLeaderboardEntry.m_steamIDUser));
			}
		}
		leaderState.state = 0;
	}

