	private static void OnGlobalStatsReceived(GlobalStatsReceived_t pCallback, bool bIOFailure)
	{
		if (!Stats.inited)
		{
			return;
		}
		lock (Stats.stats)
		{
			foreach (KeyValuePair<string, Stats.SteamStat> stat in Stats.stats)
			{
				if (stat.Value.type == 1)
				{
					try
					{
						if (winData == null)
						{
							winData = new long[30];
						}
						if (lossData == null)
						{
							lossData = new long[30];
						}
						SteamUserStats.GetGlobalStatHistory(stat.Value.win, winData, 240u);
						SteamUserStats.GetGlobalStatHistory(stat.Value.loss, lossData, 240u);
						int num = 0;
						int num2 = 0;
						for (int i = 0; i < 30; i++)
						{
							if (winData[i] <= 10000000 && lossData[i] <= 10000000)
							{
								num += (int)winData[i];
								num2 += (int)lossData[i];
							}
						}
						stat.Value.wins = num;
						stat.Value.losses = num2;
					}
					catch (Exception ex)
					{
						GameConsole.WriteLine(ex.ToString());
					}
				}
				else
				{
					SteamUserStats.GetGlobalStat(stat.Value.statName, out long pData);
					stat.Value.value = (int)pData;
				}
			}
		}
	}

