	private static bool ProcessSanctuaryDownload(int sanctIdx, LeaderboardEntry_t leaderboardEntry)
	{
		if (sanctSeen == null)
		{
			sanctSeen = new List<string>();
		}
		if (leaderboardEntry.m_steamIDUser.m_SteamID == userAccountID)
		{
			if (verbose)
			{
				GameConsole.WriteLine("It's me!");
			}
		}
		else if (sanctSeen.Contains(leaderboardEntry.m_steamIDUser.m_SteamID + "_" + sanctIdx))
		{
			if (verbose)
			{
				GameConsole.WriteLine("Already seen!");
			}
		}
		else if (PlayerMgr.player[0].sanctuaryCreed[sanctIdx] == 0)
		{
			if (verbose)
			{
				GameConsole.WriteLine("Vacant!");
			}
		}
		else
		{
			Sanctuary sanctuary = MapMgr.sanctuaryMgr.sanctuaries[sanctIdx];
			Vector2 vector = sanctuary.loc - ScrollManager.scroll;
			if (vector.X < 0f)
			{
				vector.X = 0f - vector.X;
			}
			if (vector.Y < 0f)
			{
				vector.Y = 0f - vector.Y;
			}
			if (vector.X + vector.Y < 1000f)
			{
				int num = CharMgr.AddCharacter("hero", default, 0, -1, 0);
				if (num > -1)
				{
					sanctSeen.Add(leaderboardEntry.m_steamIDUser.m_SteamID + "_" + sanctIdx);
					Character character = CharMgr.character[num];
