	internal static void QueryBossStat(Character c)
	{
		int arenaIdx = MapMgr.map.triggerMgr.GetArenaIdx(c);
		if (arenaIdx <= -1)
		{
			return;
		}
		Arena arena = MapMgr.map.triggerMgr.arena[arenaIdx];
		GameConsole.WriteLine(arena.segStrFlag);
		if (!arena.segStrFlag.StartsWith("boss "))
		{
			return;
		}
		string text = arena.segStrFlag.Substring("boss ".Length);
		if (text.Length <= 0)
		{
			GameConsole.WriteLine("No boss.");
			return;
		}
		GameConsole.WriteLine("Boss: " + text);
		string pchStatName = (text + "_win").ToUpper();
		if (SteamUserStats.GetGlobalStat(pchStatName, out long pData))
		{
			GameConsole.WriteLine("Wins: " + pData);
		}
		string pchStatName2 = (text + "_loss").ToUpper();
		if (SteamUserStats.GetGlobalStat(pchStatName2, out pData))
		{
			GameConsole.WriteLine("Losses: " + pData);
		}
		long[] array = new long[64];
		long[] array2 = new long[64];
		SteamUserStats.GetGlobalStatHistory(pchStatName, array, (uint)(8 * array.Length));
		SteamUserStats.GetGlobalStatHistory(pchStatName2, array2, (uint)(8 * array2.Length));
		for (int i = 0; i < array.Length; i++)
		{
			GameConsole.WriteLine(i + ": " + array[i] + " / " + array2[i]);
		}
	}

	internal static void IncrementStat(string s, int val)
	{
		if (!steamInitialized)
		{
			return;
		}
		if (SteamUserStats.GetStat(s, out int pData))
		{
			pData += val;
			if (pData < 1024)
			{
				SteamUserStats.SetStat(s, pData);
				SteamUserStats.StoreStats();
			}
		}
		else
		{
			GameConsole.WriteLine("Stat not found: " + s);
		}
	}

