public class Loader
{
	public static Texture2D logoTex;

	public static Texture2D logoblurTex;

	public static Texture2D circlesTex;

	public static Texture2D trrTex;

	public static bool loaded;

	private static float frame;

	private static float outFrame;

	private const int LOAD_SKA = 0;

	private const int LOAD_ESRB = 1;

	private const int LOAD_SAVE_WARN = 2;

	private const int TOTAL_SCREENS = 3;

	private static int loadScreen;

	private static GraphicsDevice GraphicsDevice;

	private static StringBuilder[] saveWarnStr;

	internal static void Init(GraphicsDevice dev, ContentManager Content)
	{
		GraphicsDevice = dev;
		logoTex = Content.Load<Texture2D>("gfx/skalogo");
		logoblurTex = Content.Load<Texture2D>("gfx/skalogoblur");
		circlesTex = Content.Load<Texture2D>("gfx/circles");
		trrTex = Content.Load<Texture2D>("gfx/trrlogo");
	}

	internal static void Update()
	{
		frame += Game1.frameTime;
		float num = 3f;
		switch (loadScreen)
		{
		case 0:
			num = 5f;
			break;
		case 1:
			num = 5f;
			break;
		case 2:
			num = 5f;
			break;
		}
		if (loadScreen >= 2)
		{
			num = ((!loaded || !(frame > num - 1f)) ? (-1f) : 0f);
		}
		if (num > -1f && frame > num - 1f)
		{
			outFrame += Game1.frameTime;
		}
		if (outFrame < 0.8f && ((frame > 0.5f && frame < num - 1f) || (frame > 0.5f && loadScreen == 2 && loaded)))
		{
			GamePadState state = GamePad.GetState(PlayerIndex.One);
			KeyboardState state2 = Keyboard.GetState(PlayerIndex.One);
			MouseState state3 = Mouse.GetState();
			if (state.Buttons.A == ButtonState.Pressed || state2.IsKeyDown(Keys.Space) || state3.LeftButton == ButtonState.Pressed)
			{
				outFrame = 1f;
			}
		}
		if (outFrame >= 1f)
		{
			frame = 0f;
			outFrame = 0f;
			loadScreen++;
			if (loadScreen >= 3)
			{
				GameStateManager.gameState = 2;
			}
		}
	}

	internal static void Draw()
	{
		GraphicsDevice.Clear(new Color(0f, 0f, 0f, 1f));
		float num = 1f;
		if (frame < 1f)
		{
			num = frame;
		}
		if (outFrame > 0f)
		{
			num -= outFrame;
		}
		if (num < 0f)
		{
			return;
		}
		float hdFactor = ScrollManager.GetHdFactor();
		switch (loadScreen)
		{
		case 2:
			if (DialogMgr.locStringsLoaded)
			{
				if (saveWarnStr == null)
				{
					saveWarnStr = WordWrap.Wrap(null, LocStrings.GetLocStr(335) + "\r\n\r\n" + LocStrings.GetLocStr(1038), 50, 0);
				}
				if (Text.loaded)
				{
					SpriteTools.BeginAlpha();
					for (int i = 0; i < saveWarnStr.Length; i++)
					{
						Text.DrawText(saveWarnStr[i], ScrollManager.screenSize / 2f + new Vector2(0f, ((float)saveWarnStr.Length * -32f - 50f + (float)i * 32f) * hdFactor), new Color(1f, 1f, 1f, num), 0.65f * hdFactor, 1);
					}
					SpriteTools.End();
				}
			}
			if (InterfaceRender.loaded)
			{
				HUD.DrawSaving(frame, ScrollManager.screenSize / 2f, num);
			}
			break;
		case 1:
			SpriteTools.BeginAlpha();
			SpriteTools.sprite.Draw(trrTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, trrTex.Width, trrTex.Height), new Color(1f, 1f, 1f, num), 0f, new Vector2(trrTex.Width, trrTex.Height) / 2f, 1f * hdFactor, SpriteEffects.None, 0f);
			SpriteTools.End();
			break;
		case 0:
			SpriteTools.BeginAdditive();
			SpriteTools.sprite.Draw(logoTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, logoTex.Width, logoTex.Height), new Color(1f, 1f, 1f, num * 0.45f * Rand.GetRandomFloat(0.9f, 1f)), 0f, new Vector2(logoTex.Width, logoTex.Height) / 2f, 1f * hdFactor, SpriteEffects.None, 0f);
			SpriteTools.sprite.Draw(logoblurTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, logoblurTex.Width, logoblurTex.Height), new Color(1f, 1f, 1f, num * ((float)Math.Sin(frame * 1.5f) * 0.25f + 0.75f) * Rand.GetRandomFloat(0.9f, 1f)), 0f, new Vector2(logoblurTex.Width, logoblurTex.Height) / 2f, 1f * hdFactor, SpriteEffects.None, 0f);
			SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.35f * Rand.GetRandomFloat(0.9f, 1f)), frame * -0.7f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 0.75f * hdFactor, SpriteEffects.None, 0f);
			SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.35f * Rand.GetRandomFloat(0.9f, 1f)), frame * 0.6f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 1f * hdFactor, SpriteEffects.None, 0f);
			SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.5f * Rand.GetRandomFloat(0.9f, 1f)), frame * -0.25f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 1.35f * hdFactor, SpriteEffects.None, 0f);
			SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.2f * Rand.GetRandomFloat(0.9f, 1f)), frame * 0.2f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 2f * hdFactor, SpriteEffects.None, 0f);
			SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.1f * Rand.GetRandomFloat(0.9f, 1f)), frame * -0.1f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 2.5f * hdFactor, SpriteEffects.None, 0f);
			SpriteTools.End();
			break;
		}
	}
}
