	public const float FRAME_MAX = 6f;

	public static float logoAlpha;

	public static void Init(ContentManager Content)
	{
		LogoDraw.Init(Content);
	}

	public static void Update(Player p)
	{
		float num = drawFrame;
		float num2 = frame;
		if (drawAlpha < 5f)
		{
			drawAlpha += Game1.frameTime;
		}
		if (DebugMgr.trailerMode)
		{
			if (GamePad.GetState(PlayerIndex.One).Buttons.RightStick == ButtonState.Pressed)
			{
				drawFrame += Game1.frameTime * 0.25f;
			}
			else
			{
				drawFrame += Game1.frameTime * 0.5f;
			}
		}
		else
		{
			drawFrame += Game1.frameTime;
		}
		if (num < 0.2f && drawFrame >= 0.2f)
		{
			Sound.PlaySnd("omistart");
		}
		if (drawFrame > 1f && (int)(frame / 4f) != (int)(num2 / 4f))
		{
			Sound.PlaySnd("omiloop");
		}
		float num3 = 0f;
		switch (p.menuMgr.curLev)
		{
		case 0:
		case 1:
		case 2:
		case 19:
		case 20:
		case 21:
		case 28:
		case 30:
		case 31:
		case 32:
		case 34:
		case 37:
			num3 = 1f;
			break;
		default:
			num3 = 0f;
			break;
		}
		if (p.menuMgr.transMode == 1)
		{
			switch (p.menuMgr.transLevel)
			{
			case 3:
			case 15:
				num3 = 0f;
				break;
			case 1:
				num3 = 1f;
				break;
			}
		}
		if (logoAlpha < num3)
		{
			logoAlpha += Game1.frameTime;
			if (logoAlpha > num3)
			{
				logoAlpha = num3;
			}
		}
		if (logoAlpha > num3)
		{
			logoAlpha -= Game1.frameTime;
			if (logoAlpha < num3)
			{
				logoAlpha = num3;
			}
		}
		if (drawFrame > 5f)
		{
			drawFrame = 5f;
		}
		if (drawFrame > 6f)
		{
			drawFrame = 6f;
		}
		if (DebugMgr.trailerMode)
		{
			p.camMgr.dotsMgr.Update(Game1.frameTime, 0);
		}
	}

	public static void Prepare(Player p, GraphicsDevice GraphicsDevice, RenderTarget2D goalTarg)
	{
		GraphicsDevice.SetRenderTarget(goalTarg);
		GraphicsDevice.Clear(Color.Black);
		scale = ScrollManager.screenSize.Y / 1180f;
		float num = scale * (1f - drawFrame / 100f);
		float num2 = frame;
		if (DebugMgr.trailerMode)
		{
			num2 *= 0.5f;
		}
		scale *= 1f - drawFrame / 100f + (float)Math.Cos(num2) * 0.005f;
		if (p.menuMgr.transMode == 1)
		{
			int transLevel = p.menuMgr.transLevel;
			if (transLevel == 3 || transLevel == 15)
			{
				scale += p.menuMgr.transFrame * 0.05f;
				num += p.menuMgr.transFrame * 0.05f;
			}
		}
		Vector2 origin = ScrollManager.screenSize / 2f;
		LogoDraw.Prepare(num2, drawFrame, origin, scale, num, p);
	}

	public static float GetAlphaVal(float drawFrame, float thresh, float ramp)
	{
		if (drawFrame < 0f)
		{
			return 0f;
		}
		if (drawFrame > 5f)
		{
			return 6f - drawFrame;
		}
		if (drawFrame < thresh - ramp)
		{
			return 0f;
		}
		if (drawFrame < thresh)
		{
			return (drawFrame - (thresh - ramp)) / ramp + Rand.GetRandomFloat(0f, 0.01f);
		}
		return 1f;
	}

	public static float GetTrigAdjustedVal(float val, float thresh)
	{
		if (val > thresh)
		{
			return 0f;
		}
		return 1f - (float)Math.Cos((thresh - val) * 0.35f);
	}

	internal static void Draw(RenderTarget2D auxTarg)
	{
		LogoDraw.Draw(auxTarg);
	}
}
