	public static void Update()
	{
		frame += Game1.frameTime;
		if (maxScroll > -1f || DebugMgr.quickCreditsMode)
		{
			outFrame += Game1.frameTime;
			if (outFrame > 6f)
			{
				Player mainPlayer = PlayerMgr.GetMainPlayer();
				CharMgr.GetPlayerCharacter(mainPlayer).loc = mainPlayer.respawnLoc;
				GameStateManager.gameState = 2;
				GameStateManager.uberDeadFrame = 0f;
				GameStateManager.upsideDown = false;
				GameStateManager.vanquishedFrame = 0f;
				Game1.charSaveList.Init(mainPlayer);
				mainPlayer.menuMgr.curLev = 0;
				mainPlayer.menuMgr.transMode = 4;
				mainPlayer.menuMgr.transFrame = 0f;
			}
		}
	}

	public static void Init()
	{
		frame = 0f;
		if (creditLine == null)
		{
			InitData();
		}
		GameStateManager.gameState = 4;
		maxScroll = -1f;
		outFrame = 0f;
		Player mainPlayer = PlayerMgr.GetMainPlayer();
		mainPlayer.respawnLoc = new Vector2(900f, 14800f);
		mainPlayer.respawnLoc.Y = CharCols.GetGround(mainPlayer.respawnLoc);
		mainPlayer.sanctuaryRespawnLoc = mainPlayer.respawnLoc;
		Character playerCharacter = CharMgr.GetPlayerCharacter(mainPlayer);
		if (mainPlayer.playthroughNumber < 7)
		{
			mainPlayer.playthroughNumber++;
		}
		List<string> list = new List<string>();
		foreach (string flag in mainPlayer.flags)
		{
			if (flag.StartsWith("#wi#_"))
			{
				list.Add(flag);
			}
		}
		mainPlayer.flags.Clear();
		foreach (string item in list)
		{
			mainPlayer.flags.Add(item);
		}
		mainPlayer.challenge.SetChallengeFlags();
		for (int i = 0; i < mainPlayer.playerInv.inventory.Length; i++)
		{
			if (mainPlayer.playerInv.inventory[i] != null)
			{
				InvLoot invLoot = mainPlayer.playerInv.inventory[i];
				LootDef lootDef = LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx];
				if (lootDef.category == 3 && lootDef.type == 2)
				{
					mainPlayer.playerInv.inventory[i] = null;
				}
			}
		}
		mainPlayer.flags.Add("chose_creed");
		mainPlayer.playerInv.RemoveKeys();
		mainPlayer.ResetSanctuaries();
		MapMgr.sanctuaryMgr.InitFromMap();
		MapMgr.sanctuaryMgr.InitToPlayer(mainPlayer);
		mainPlayer.WriteCharSave(playerCharacter);
	}

	public static void Draw(GraphicsDevice GraphicsDevice)
	{
		float hdFactor = ScrollManager.GetHdFactor();
		GraphicsDevice.Clear(new Color(0f, 0f, 0f, 1f));
		SpriteTools.BeginAdditive();
		float num = (frame - 3f) * 100f;
		if (num < 0f)
		{
			num = 0f;
		}
		if (maxScroll > -1f && num > maxScroll)
		{
			num = maxScroll;
		}
		float num2 = 48f * hdFactor;
		for (int i = 0; i < creditLine.Length; i++)
		{
			if (creditLine[i].name == null)
			{
				continue;
			}
			float num3 = num;
			if (i > creditLine.Length - 3 && maxScroll > -1f && num3 > maxScroll)
			{
				num3 = maxScroll;
			}
			Vector2 loc = new Vector2(ScrollManager.screenSize.X / 2f, (float)i * num2 - num3 * hdFactor + ScrollManager.screenSize.Y / 2f);
			if (loc.Y > 100f * hdFactor && loc.Y < ScrollManager.screenSize.Y - 100f * hdFactor)
			{
				float num4 = 1f;
				if (loc.Y < 200f * hdFactor)
				{
					num4 = (loc.Y - 100f * hdFactor) / (100f * hdFactor);
				}
				if (loc.Y > ScrollManager.screenSize.Y - 200f * hdFactor)
				{
					num4 = (ScrollManager.screenSize.Y - 100f * hdFactor - loc.Y) / (100f * hdFactor);
				}
				if (outFrame > 3f)
				{
					num4 *= (6f - outFrame) / 3f;
					if (num4 < 0f)
					{
						num4 = 0f;
					}
				}
				Color color = new Color(1f, 1f, 1f, num4);
				switch (creditLine[i].type)
				{
				case 2:
					color = new Color(1f, 1f, 0.7f, num4);
					break;
				case 1:
					color = new Color(0.7f, 0.7f, 0.7f, num4);
					break;
				}
				Text.DrawText(creditLine[i].name, loc, color, 0.55f * hdFactor, 1);
			}
			if (i == creditLine.Length - 1 && loc.Y < ScrollManager.screenSize.Y / 2f)
			{
				maxScroll = num;
			}
		}
		if (frame < 1f)
		{
			SpriteTools.sprite.Draw(Game1.nullTex, new Rectangle(0, 0, (int)ScrollManager.screenSize.X, (int)ScrollManager.screenSize.Y), new Color(1f, 1f, 1f, 1f - frame));
		}
		if (outFrame > 3f)
		{
			SpriteTools.sprite.Draw(Game1.nullTex, new Rectangle(0, 0, (int)ScrollManager.screenSize.X, (int)ScrollManager.screenSize.Y), new Color(1f, 1f, 1f, (outFrame - 3f) / 3f));
		}
		SpriteTools.End();
	}
}

